#include <stdio.h>

int main(void)
{
    int c;

    if (scanf("%d", &c) != 1) {     /* 检查返回值：读入失败就直接退出 */
        return 1;
    }

    double f = c / 5.0 * 9 + 32;    /* 关键：5.0 让除法变成浮点除法 */

    printf("%.2f\n", f);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 100 || n > 999) {
        return 1;
    }

    int b = n / 100;          /* 百位 */
    int s = n / 10 % 10;      /* 十位：先去掉个位，再取余 */
    int g = n % 10;           /* 个位 */

    printf("百位:%d 十位:%d 个位:%d\n", b, s, g);
    printf("各位数字之和:%d\n", b + s + g);
    printf("逆序数:%d\n", g * 100 + s * 10 + b);
    return 0;
}

#include <stdio.h>

int main(void)
{
    char ch;
    int kind;             /* 1 大写 2 小写 3 数字 4 其他 */
    int value = -1;
    char conv;

    if (scanf(" %c", &ch) != 1) {
        return 1;
    }

    conv = ch;
    if (ch >= 'A' && ch <= 'Z') {
        conv = ch + 32;         /* 大写转小写：ASCII 差 32 */
        kind = 1;
    } else if (ch >= 'a' && ch <= 'z') {
        conv = ch - 32;
        kind = 2;
    } else if (ch >= '0' && ch <= '9') {
        value = ch - '0';       /* 字符转数值：减去 '0' 的 48 */
        kind = 3;
    } else {
        kind = 4;
    }

    printf("字符:%c\n", ch);
    printf("ASCII:%d\n", ch);
    printf("转换后:%c\n", conv);
    printf("数值:%d\n", value);

    switch (kind) {
        case 1: printf("类型:大写字母\n"); break;
        case 2: printf("类型:小写字母\n"); break;
        case 3: printf("类型:数字字符\n"); break;
        default: printf("类型:其他\n"); break;
    }
    return 0;
}

#include <stdio.h>

int main(void)
{
    int w;
    double fee;

    if (scanf("%d", &w) != 1 || w < 0) {
        return 1;
    }

    if (w > 20) {
        fee = 10 * 2 + 10 * 3 + (w - 20) * 5;   /* 三档分别计价再相加 */
    } else if (w > 10) {
        fee = 10 * 2 + (w - 10) * 3;
    } else {
        fee = w * 2;
    }

    printf("水费:%.2f元\n", fee);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int choice, value;

    if (scanf("%d %d", &choice, &value) != 2) {
        return 1;
    }

    switch (choice) {
        case 1:                                     /* 秒 -> 时:分:秒 */
            printf("%02d:%02d:%02d\n", value / 3600, value % 3600 / 60, value % 60);
            break;
        case 2:                                     /* 摄氏 -> 华氏 */
            printf("%.2f\n", value / 5.0 * 9 + 32);
            break;
        case 3:                                     /* 厘米 -> 米 + 厘米 */
            printf("%d米%d厘米\n", value / 100, value % 100);
            break;
        default:
            printf("非法选项\n");
            break;
    }
    return 0;
}
